BEGIN;
INSERT INTO public.agents_skill_catalog(slug,display_name,description,category,emoji,parameters_schema,action_type,action_config,default_usage_mode) VALUES ('listar_contas_meta_ads','Listar contas Meta Ads','Descobre conexões Meta direta e Zernio da empresa e suas contas de anúncios. Se houver várias, peça escolha de connection_id; nunca troque o provedor por conta própria.','advertising','📊','{"type": "object", "properties": {"connection_id": {"type": "string", "description": "ID retornado por listar_contas_meta_ads. Inclui provedor. Nunca invente."}, "ad_account_id": {"type": "string", "pattern": "^act_[0-9]+$"}, "from_date": {"type": "string", "description": "AAAA-MM-DD; exige to_date"}, "to_date": {"type": "string"}, "level": {"type": "string", "enum": ["account", "campaign", "adset", "ad"]}, "cursor": {"type": "string", "description": "Cursor retornado pelo provedor (Meta / insights)."}, "page": {"type": "integer", "minimum": 1, "description": "P\u00e1gina da \u00e1rvore Zernio."}, "limit": {"type": "integer", "minimum": 1, "maximum": 100}}, "additionalProperties": false}','edge_function','{"name": "ads-read"}','always') ON CONFLICT(slug) DO UPDATE SET description=excluded.description,parameters_schema=excluded.parameters_schema,action_config=excluded.action_config;
INSERT INTO public.agents_skill_catalog(slug,display_name,description,category,emoji,parameters_schema,action_type,action_config,default_usage_mode) VALUES ('consultar_campanhas_meta_ads','Consultar campanhas Meta Ads','Lê campanhas, conjuntos e anúncios usando a conexão escolhida (Meta direta ou Zernio). Resultados paginados; não altera campanhas ou gastos.','advertising','📊','{"type": "object", "properties": {"connection_id": {"type": "string", "description": "ID retornado por listar_contas_meta_ads. Inclui provedor. Nunca invente."}, "ad_account_id": {"type": "string", "pattern": "^act_[0-9]+$"}, "from_date": {"type": "string", "description": "AAAA-MM-DD; exige to_date"}, "to_date": {"type": "string"}, "level": {"type": "string", "enum": ["account", "campaign", "adset", "ad"]}, "cursor": {"type": "string", "description": "Cursor retornado pelo provedor (Meta / insights)."}, "page": {"type": "integer", "minimum": 1, "description": "P\u00e1gina da \u00e1rvore Zernio."}, "limit": {"type": "integer", "minimum": 1, "maximum": 100}}, "additionalProperties": false}','edge_function','{"name": "ads-read"}','always') ON CONFLICT(slug) DO UPDATE SET description=excluded.description,parameters_schema=excluded.parameters_schema,action_config=excluded.action_config;
INSERT INTO public.agents_skill_catalog(slug,display_name,description,category,emoji,parameters_schema,action_type,action_config,default_usage_mode) VALUES ('consultar_metricas_meta_ads','Consultar métricas Meta Ads','Lê gasto, impressões, cliques, CTR, CPC, CPM, alcance, ações e ROAS quando disponíveis. Meta direta ou Zernio; padrão últimos 30 dias. Não invente dados ausentes.','advertising','📊','{"type": "object", "properties": {"connection_id": {"type": "string", "description": "ID retornado por listar_contas_meta_ads. Inclui provedor. Nunca invente."}, "ad_account_id": {"type": "string", "pattern": "^act_[0-9]+$"}, "from_date": {"type": "string", "description": "AAAA-MM-DD; exige to_date"}, "to_date": {"type": "string"}, "level": {"type": "string", "enum": ["account", "campaign", "adset", "ad"]}, "cursor": {"type": "string", "description": "Cursor retornado pelo provedor (Meta / insights)."}, "page": {"type": "integer", "minimum": 1, "description": "P\u00e1gina da \u00e1rvore Zernio."}, "limit": {"type": "integer", "minimum": 1, "maximum": 100}}, "additionalProperties": false}','edge_function','{"name": "ads-read"}','always') ON CONFLICT(slug) DO UPDATE SET description=excluded.description,parameters_schema=excluded.parameters_schema,action_config=excluded.action_config;

-- Additive: preserve legacy Meta API, credentials, approval modes and custom prompts.
INSERT INTO public.agents_tools(agent_id,name,description,parameters_schema,action_type,action_config,usage_mode,is_active)
SELECT a.id,c.slug,c.description,c.parameters_schema,c.action_type,c.action_config,'always',true
FROM public.agents_registry a CROSS JOIN public.agents_skill_catalog c
WHERE c.slug IN ('listar_contas_meta_ads','consultar_campanhas_meta_ads','consultar_metricas_meta_ads')
AND (a.slug='template_vinicius_trafego' OR a.parent_agent_id IN (SELECT id FROM public.agents_registry WHERE slug='template_vinicius_trafego') OR EXISTS(SELECT 1 FROM public.agents_tools t WHERE t.agent_id=a.id AND t.name='meta_api'))
ON CONFLICT(agent_id,name) DO NOTHING;
UPDATE public.agents_registry SET description='TEMPLATE: gestor de tráfego Meta Ads. Consulta contas, campanhas e métricas via Meta direta ou Zernio da empresa. Integração direta existente preservada.',required_providers=array_remove(required_providers,'meta_ads') WHERE slug='template_vinicius_trafego';
UPDATE public.agents_registry a SET system_prompt=system_prompt || E'\n\n## Conexões Meta Ads (direta ou Zernio)\nPara consultas, comece por listar_contas_meta_ads e use consultar_campanhas_meta_ads e consultar_metricas_meta_ads. Essas habilidades resolvem a credencial da empresa no servidor. Com várias conexões, peça a escolha; guarde connection_id e ad_account_id na memória, nunca tokens. A escolha deve permanecer no mesmo provedor; falha de permissão não autoriza trocar. A ferramenta meta_api existente continua exclusiva da Meta direta. As novas habilidades são somente leitura; não prometa criação, pausa ou alteração via Zernio. Diferencie erro, dado ausente e zero; respeite paginação e período. Não solicite chaves no chat. O playground permite essas consultas reais e exibe as chamadas.',updated_at=now()
WHERE EXISTS(SELECT 1 FROM public.agents_tools t WHERE t.agent_id=a.id AND t.name='listar_contas_meta_ads') AND system_prompt NOT LIKE '%## Conexões Meta Ads (direta ou Zernio)%';
COMMIT;
